<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Universe Civilization: Empire at Wars Dashboard Wireframe</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">S</div><div><strong>UNIVERSE CIVILIZATION: EMPIRE AT WARS</strong><small>COMMAND INTERFACE</small></div></div><div class="profile"><div class="avatar">CT</div><div><strong>Commander Tanang</strong><span>Tau'ri realm</span></div></div><nav class="main-nav"><div class="nav-caption">Navigation</div><ul><li class="nav-group open"><a class="nav-link active" href="#"><span class="nav-icon">⌂</span><span>Command Center</span><span class="chevron">›</span></a><ul class="submenu"><li><a class="sub-link active" href="#">Account Information</a></li><li><a class="sub-link" href="#">Resources</a></li><li><a class="sub-link" href="#">Income</a></li><li><a class="sub-link" href="#">Military Scores</a></li></ul></li><li class="nav-group open"><a class="nav-link" href="#"><span class="nav-icon">⚔</span><span>Attack</span><span class="chevron">›</span></a><ul class="submenu"><li><a class="sub-link" href="#">Targets</a></li><li><a class="sub-link" href="#">Spy</a></li><li><a class="sub-link" href="#">Sabotage</a></li></ul></li><li class="nav-group"><a class="nav-link" href="#"><span class="nav-icon">▣</span><span>Armory</span><span class="chevron">›</span></a></li><li class="nav-group"><a class="nav-link" href="#"><span class="nav-icon">◈</span><span>Training</span><span class="chevron">›</span></a></li><li class="nav-group"><a class="nav-link" href="#"><span class="nav-icon">◇</span><span>Technology</span><span class="chevron">›</span></a></li><li class="nav-group"><a class="nav-link" href="#"><span class="nav-icon">◎</span><span>Intelligence</span><span class="chevron">›</span></a></li><li class="nav-group"><a class="nav-link" href="#"><span class="nav-icon">